/* @autogenerated */
package net.civeira.phylax.common.crypto;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.mockStatic;

import java.security.NoSuchAlgorithmException;

import javax.crypto.Mac;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.MockedStatic;

@DisplayName("SecretDigester")
class SecretDigesterUnitTest {

  @Test
  @DisplayName("Should use the first valid pepper when no current one is configured")
  void shouldDefaultToFirstPepper() {
    // Arrange — a ring with invalid entries before the valid ones
    SecretDigester digester =
        new SecretDigester("no-separator, bad id!:x, p3:, p1:one, p2:two", "");

    // Act / Assert — the first valid pepper signs the digest
    assertTrue(digester.digest("secret").startsWith(SecretDigester.PREFIX + "p1:"));
    assertFalse(digester.needsRehash(digester.digest("secret")));
  }

  @Test
  @DisplayName("Should fall back to a generic pepper when none is configured")
  void shouldFallBackToGenericPepper() {
    SecretDigester digester = new SecretDigester("", "");
    assertTrue(digester.digest("secret").startsWith(SecretDigester.PREFIX + "p0:"));
  }

  @Test
  @DisplayName("Should reject a current pepper missing from the ring")
  void shouldRejectUnknownCurrentPepper() {
    assertThrows(IllegalArgumentException.class, () -> new SecretDigester("p1:one", "p9"));
  }

  @Test
  @DisplayName("Should not verify digests without a known pepper id")
  void shouldNotVerifyUnknownDigests() {
    SecretDigester digester = new SecretDigester("p1:one", "p1");
    assertFalse(digester.verify("secret", null));
    assertFalse(digester.verify("secret", "sha1:abc"));
    assertFalse(digester.verify("secret", SecretDigester.PREFIX + "p9:abc"));
  }

  @Test
  @DisplayName("Should recognise only well formed digests")
  void shouldRecogniseWellFormedDigests() {
    assertFalse(SecretDigester.isSupported(null));
    assertFalse(SecretDigester.isSupported("sha1:abc"));
    assertFalse(SecretDigester.isSupported(SecretDigester.PREFIX + "p1"));
    assertFalse(SecretDigester.isSupported(SecretDigester.PREFIX + ":abc"));
    assertFalse(SecretDigester.isSupported(SecretDigester.PREFIX + "p1:"));
    assertTrue(SecretDigester.isSupported(SecretDigester.PREFIX + "p1:abc"));
  }

  @Test
  @DisplayName("Should ask for rehash on malformed digests")
  void shouldRehashMalformedDigests() {
    assertTrue(new SecretDigester("p1:one", "p1").needsRehash("plain"));
  }

  @Test
  @DisplayName("Should report HMAC unavailability as an illegal state")
  void shouldWrapMissingHmac() {
    SecretDigester digester = new SecretDigester("p1:one", "p1");
    try (MockedStatic<Mac> mac = mockStatic(Mac.class)) {
      mac.when(() -> Mac.getInstance(anyString()))
          .thenThrow(new NoSuchAlgorithmException("missing"));
      IllegalStateException ex =
          assertThrows(IllegalStateException.class, () -> digester.digest("secret"));
      assertEquals("HMAC-SHA256 is unavailable", ex.getMessage());
    }
  }
}
